class c{calculateVAT(t,o=.15){const n=t*o,r=n*.18,a=t+n+r,e=t;return{baseAmount:Math.round(t*100)/100,commission:Math.round(n*100)/100,vatOnCommission:Math.round(r*100)/100,totalCharged:Math.round(a*100)/100,netToProvider:Math.round(e*100)/100}}getCurrentRate(){return .18*100}roundToCurrency(t){return Math.round(t*100)/100}calculateVATAmount(t){const o=t*.15;return Math.round(o*.18*100)/100}calculateTotalWithVAT(t){const o=t*.15,n=o*.18;return Math.round((t+o+n)*100)/100}}const s=new c,A={defaultPaymentMethod:"reservation_hold"};function M(){return A.defaultPaymentMethod}export{M as g,s as v};
